// ============================================================
// TutorBot · Modulo REGISTRO / IDENTIFICACION
// Tres pasos:
//   1. inicio         -> pide el codigo de estudiante (10 digitos)
//   2. identificar    -> valida el codigo, o inicia el alta si escribe NUEVO
//   3. guardar_nombre -> crea el estudiante y le entrega su codigo
//
// Sin identificacion no se permite ninguna otra accion: TUTORIAS.id_estudiante
// tiene que apuntar a alguien real.
// ============================================================
const ctx = $input.first().json;
const cfg = $('Config').first().json;

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const estudiantes = filas('Leer ESTUDIANTES').filter(e => String(e.id_estudiante || '') !== '');

const soloDigitos = s => String(s == null ? '' : s).replace(/[^0-9]/g, '');
const esCodigo = s => /^[0-9]{10}$/.test(soloDigitos(s));

const MENU = [
  '',
  'Menu principal:',
  '1) Solicitar tutoria',
  '2) Ver mis tutorias',
  '3) Cancelar una tutoria',
  '4) Ayuda',
  '',
  'Responde con el numero de la opcion.'
].join('\n');

function sesion(pantalla, paso, datos) {
  return {
    telegram_user: ctx.telegram_user,
    pantalla_actual: pantalla,
    paso_actual: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    actualizado_en: cfg.ahora_iso
  };
}

function salida(o) {
  return [{ json: Object.assign({
    telegram_user: ctx.telegram_user,
    chat_id: ctx.chat_id,
    ruta: ctx.ruta,
    submodo: ctx.submodo,
    accion: 'sin_accion',
    estudiante_row: null,
    tutoria_row: null,
    notificar: null,
    evento: 'registro',
    detalle: ''
  }, o) }];
}

// ------------------------------------------------------------
// Paso 1 · pedir el codigo de estudiante
// ------------------------------------------------------------
if (ctx.submodo === 'inicio') {
  return salida({
    mensaje: [
      'Hola ' + (ctx.nombre_telegram || '') + '. Soy TutorBot, el asistente de asesorias academicas.',
      '',
      'Para empezar necesito identificarte.',
      '',
      'Escribe tu codigo de estudiante (10 numeros).',
      'Si es tu primera vez y no tienes codigo, escribe NUEVO.'
    ].join('\n'),
    sesion: sesion('IDENTIFICACION', 1, {}),
    evento: 'identificacion_solicitada'
  });
}

// ------------------------------------------------------------
// Paso 2 · validar el codigo recibido
// ------------------------------------------------------------
if (ctx.submodo === 'identificar') {
  const entrada = String(ctx.texto || '').trim();

  if (/^nuevo$/i.test(entrada) || entrada === '0') {
    return salida({
      mensaje: [
        'Perfecto, te registro.',
        '',
        'Necesito tu nombre completo (nombre y apellido).',
        'Escribelo tal como aparece en tu matricula.'
      ].join('\n'),
      sesion: sesion('REGISTRO_NOMBRE', 2, {}),
      evento: 'registro_iniciado'
    });
  }

  if (!esCodigo(entrada)) {
    return salida({
      mensaje: [
        'Ese codigo no tiene el formato correcto.',
        '',
        'Debe ser exactamente 10 numeros, por ejemplo: 1002345678',
        'Si no tienes codigo todavia, escribe NUEVO.'
      ].join('\n'),
      sesion: sesion('IDENTIFICACION', 1, {}),
      evento: 'identificacion_rechazada',
      detalle: 'formato invalido: "' + entrada.slice(0, 30) + '"'
    });
  }

  const codigoPedido = soloDigitos(entrada);
  const fila = estudiantes.find(e => soloDigitos(e.id_estudiante) === codigoPedido) || null;

  if (!fila) {
    return salida({
      mensaje: [
        'No encontre el codigo ' + codigoPedido + ' en el sistema.',
        '',
        'Revisa los numeros y vuelve a escribirlo,',
        'o escribe NUEVO para registrarte.'
      ].join('\n'),
      sesion: sesion('IDENTIFICACION', 1, {}),
      evento: 'identificacion_fallida',
      detalle: 'codigo inexistente: ' + codigoPedido
    });
  }

  // El codigo ya vinculado a otra cuenta no se reasigna desde el chat: seria
  // suplantacion con solo adivinar 10 digitos (RN-27).
  const dueno = String(fila.telegram_user || '').trim();
  if (dueno && dueno !== ctx.telegram_user) {
    return salida({
      mensaje: [
        'El codigo ' + codigoPedido + ' ya esta vinculado a otra cuenta de Telegram.',
        '',
        'Si es tu codigo y cambiaste de numero, escribe a la coordinacion academica',
        'para que actualicen el registro.'
      ].join('\n'),
      sesion: sesion('IDENTIFICACION', 1, {}),
      evento: 'identificacion_bloqueada',
      detalle: 'codigo ' + codigoPedido + ' ya vinculado a otra cuenta'
    });
  }

  if (String(fila.estado || 'Activo').toLowerCase() !== 'activo') {
    return salida({
      mensaje: [
        'Tu registro esta marcado como ' + fila.estado + '.',
        '',
        'Escribe a la coordinacion academica para reactivarlo.'
      ].join('\n'),
      sesion: sesion('IDENTIFICACION', 1, {}),
      evento: 'identificacion_bloqueada',
      detalle: 'estudiante ' + codigoPedido + ' en estado ' + fila.estado
    });
  }

  const vinculada = Object.assign({}, fila);
  delete vinculada.row_number;
  vinculada.telegram_user = ctx.telegram_user;

  return salida({
    mensaje: 'Listo, ' + String(fila.nombre || '').split(' ')[0] +
             '. Quedaste identificado con el codigo ' + codigoPedido + '.' + MENU,
    sesion: sesion('MENU', 0, {}),
    accion: 'crear_estudiante',
    estudiante_row: vinculada,
    evento: 'estudiante_identificado',
    detalle: codigoPedido
  });
}

// ------------------------------------------------------------
// Paso 3 · alta: validar el nombre y generar el codigo
// ------------------------------------------------------------
const nombre = String(ctx.texto || '').replace(/\s+/g, ' ').trim();
const soloLetras = /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ' .-]+$/.test(nombre);
const valido = nombre.length >= 5 && nombre.length <= 60 && soloLetras && nombre.split(' ').length >= 2;

if (!valido) {
  return salida({
    mensaje: [
      'Ese nombre no parece valido.',
      '',
      'Debe tener nombre y apellido, entre 5 y 60 caracteres, sin numeros ni simbolos.',
      'Ejemplo: Ana Maria Rojas'
    ].join('\n'),
    sesion: sesion('REGISTRO_NOMBRE', 2, {}),
    evento: 'registro_rechazado',
    detalle: 'nombre invalido: "' + ctx.texto.slice(0, 40) + '"'
  });
}

// ---- Codigo de 10 digitos, derivado y unico (RN-25, RN-26) ----
// Derivado: el mismo telegram_user produce siempre el mismo codigo base, asi que
// repetir el alta no crea un segundo estudiante.
// Unico: si ese numero ya lo tiene otra persona, se avanza al siguiente libre.
const usados = new Set(estudiantes.map(e => soloDigitos(e.id_estudiante)));
const mio = estudiantes.find(e => String(e.telegram_user || '') === ctx.telegram_user) || null;

let codigo;
if (mio) {
  codigo = soloDigitos(mio.id_estudiante);
} else {
  let n = Number(soloDigitos(ctx.telegram_user).slice(-10));
  if (!isFinite(n) || n < 1000000000) n = 1000000000 + (Math.abs(n || 0) % 1000000000);
  let intentos = 0;
  while (usados.has(String(n)) && intentos < 2000) {
    n = n + 1 > 9999999999 ? 1000000000 : n + 1;
    intentos++;
  }
  codigo = String(n);
}

return salida({
  mensaje: [
    'Registro completado, ' + nombre.split(' ')[0] + '.',
    '',
    'TU CODIGO DE ESTUDIANTE ES: ' + codigo,
    'Guardalo: lo necesitaras para identificarte.',
    MENU
  ].join('\n'),
  sesion: sesion('MENU', 0, {}),
  accion: 'crear_estudiante',
  estudiante_row: {
    id_estudiante: codigo,
    telegram_user: ctx.telegram_user,
    nombre: nombre,
    programa: '',
    estado: 'Activo',
    fecha_registro: cfg.ahora_iso
  },
  evento: 'estudiante_registrado',
  detalle: codigo
});

// ============================================================
// TutorBot · Normalizar respuesta del modulo
// Punto unico de convergencia de los 7 modulos. Garantiza que, sin importar
// que rama se ejecuto, exista siempre: mensaje, sesion, accion y fila de log.
// Hay una copia de este nodo por rama: 'Normalizar REGISTRO', 'Normalizar MENU', etc.
// Los nodos siguientes de cada rama leen del suyo, no de uno compartido.
// ============================================================
const it = $input.first().json;
const cfg = $('Config').first().json;

// ---- Rastro de la IA (si esta ejecucion paso por el interprete) ----
// $('Nodo') lanza error si el nodo no se ejecuto en esta rama: se captura.
// En el sub-workflow el contexto llega por 'Ejecutar modulo'; en un flujo unico
// viene del nodo de validacion. Se prueban los dos y se ignora el que no exista.
let ia = null;
for (const nombre of ['Ejecutar modulo', 'Validar interpretacion IA']) {
  try {
    const j = $(nombre).first().json;
    if (j && j.ia_usada) { ia = j; break; }
  } catch (e) { /* ese nodo no existe en este workflow */ }
}

const ACCIONES = ['sin_accion', 'crear_estudiante', 'crear_tutoria', 'actualizar_tutoria'];
const accion = ACCIONES.includes(it.accion) ? it.accion : 'sin_accion';

// Telegram rechaza mensajes vacios y corta en 4096 caracteres
let mensaje = String(it.mensaje == null ? '' : it.mensaje).trim();
if (!mensaje) mensaje = 'Ocurrio algo inesperado y no pude preparar una respuesta. Escribe /menu para reiniciar.';
// El estudiante debe VER lo que el modelo entendio antes de que se reserve nada
if (ia && ia.ia_aviso) mensaje = ia.ia_aviso + '\n\n' + mensaje;
// Telegram interpreta el texto como HTML: hay que escapar estos tres caracteres.
// Sin esto, un "<" en el texto rompe el envio entero con "can't parse entities".
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
mensaje = esc(mensaje);
if (mensaje.length > 3900) mensaje = mensaje.slice(0, 3900) + '\n\n[mensaje recortado]';

const sesion = it.sesion || {
  telegram_user: it.telegram_user, pantalla_actual: 'MENU', paso_actual: '0',
  datos_parciales: '{}', actualizado_en: cfg.ahora_iso
};

const tutoria = it.tutoria_row || null;
const estudiante = it.estudiante_row || null;

let entidad = 'sesion', id_entidad = String(it.telegram_user || '');
if (tutoria)        { entidad = 'tutoria';    id_entidad = String(tutoria.id_tutoria || ''); }
else if (estudiante){ entidad = 'estudiante'; id_entidad = String(estudiante.id_estudiante || ''); }

// Fila de LOG_EVENTOS: es la trazabilidad que pide la coordinacion
const log = {
  id_evento: 'EV-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 9000 + 1000),
  timestamp: cfg.ahora_iso,
  telegram_user: String(it.telegram_user || ''),
  evento: String(it.evento || 'interaccion'),
  entidad: entidad,
  id_entidad: id_entidad,
  detalle: String(it.detalle == null ? '' : it.detalle).slice(0, 300)
};
// Auditoria del uso de IA: que se le mando, que devolvio y si se acepto
if (ia) {
  log.detalle = (log.detalle + ' | IA:' + ia.ia_intencion +
    '/' + (ia.ia_materia || '-') + '/' + (ia.ia_fecha || '-') +
    ' conf=' + ia.ia_confianza +
    (ia.ia_fallo ? ' descartado=' + ia.ia_fallo : '') +
    ' txt="' + String(ia.ia_texto_original || '').slice(0, 60) + '"').slice(0, 300);
}

return [{
  json: {
    telegram_user: String(it.telegram_user || ''),
    chat_id: String(it.chat_id || ''),
    ruta: it.ruta || '', submodo: it.submodo || '',
    mensaje: mensaje,
    sesion: sesion,
    accion: accion,
    estudiante_row: estudiante,
    tutoria_row: tutoria,
    notificar: it.notificar && it.notificar.chat_id
      ? Object.assign({}, it.notificar, { mensaje: esc(it.notificar.mensaje) })
      : null,
    ia_usada: !!ia,
    ia_fallo: ia ? ia.ia_fallo : '',
    log: log
  }
}];
